test_that("posterior_predict for categorical and related models runs without erros", {
  withr::local_seed(330L)
  brms_setup("posterior_predict:331",
    set.seed(1234)
  )
  brms_setup("posterior_predict:332",
    ns <- 50
  )
  brms_setup("posterior_predict:333",
    nobs <- 8
  )
  brms_setup("posterior_predict:334",
    ncat <- 3
  )
  brms_setup("posterior_predict:335",
    prep <- structure(list(ndraws = ns, nobs = nobs), class = "brmsprep")
  )
  brms_setup("posterior_predict:336",
    prep$dpars <- list(
      mu1 = array(rnorm(ns*nobs, 0, 0.1), dim = c(ns, nobs)),
      mu2 = array(rnorm(ns*nobs, 0, 0.1), dim = c(ns, nobs))
    )
  )
  brms_setup("posterior_predict:340",
    prep$data <- list(Y = rep(1:ncat, 2), ncat = ncat)
  )
  brms_setup("posterior_predict:341",
    prep$family <- categorical()
  )
  brms_setup("posterior_predict:342",
    prep$refcat <- 1
  )
  brms_setup("posterior_predict:343",
    pred <- sapply(1:nobs, brms_adapt_posterior_predict, fun = "categorical", 
        prep = prep)
  )
  brms_port("posterior_predict:344", "pass",
    "",
    expect_equal(dim(pred), c(ns, nobs))
  )
  brms_setup("posterior_predict:346",
    prep$data$trials <- sample(1:20, nobs)
  )
  brms_setup("posterior_predict:347",
    prep$family <- multinomial()
  )
  brms_setup("posterior_predict:348",
    pred <- brms_adapt_posterior_predict("multinomial", i = sample(1:nobs, 
        1), prep = prep)
  )
  brms_port("posterior_predict:349", "pass",
    "",
    expect_equal(dim(pred), c(ns, ncat))
  )
  brms_setup("posterior_predict:351",
    prep$data$trials <- sample(1:20, nobs)
  )
  brms_setup("posterior_predict:352",
    prep$dpars$phi <- rexp(ns, 1)
  )
  brms_setup("posterior_predict:353",
    prep$family <- dirichlet_multinomial()
  )
  brms_setup("posterior_predict:354",
    pred <- brms_adapt_posterior_predict("dirichlet_multinomial", 
        i = sample(1:nobs, 1), prep = prep)
  )
  brms_port("posterior_predict:355", "pass",
    "",
    expect_equal(dim(pred), c(ns, ncat))
  )
  brms_setup("posterior_predict:357",
    prep$dpars$phi <- rexp(ns, 1)
  )
  brms_setup("posterior_predict:358",
    prep$family <- dirichlet()
  )
  brms_setup("posterior_predict:359",
    pred <- brms_adapt_posterior_predict("dirichlet", i = sample(1:nobs, 
        1), prep = prep)
  )
  brms_port("posterior_predict:360", "pass",
    "",
    expect_equal(dim(pred), c(ns, ncat))
  )
  brms_port("posterior_predict:361", "pass",
    "",
    expect_equal(rowSums(pred), rep(1, nrow(pred)))
  )
  brms_setup("posterior_predict:363",
    prep$family <- brmsfamily("dirichlet2")
  )
  brms_setup("posterior_predict:364",
    prep$dpars$mu1 <- rexp(ns, 10)
  )
  brms_setup("posterior_predict:365",
    prep$dpars$mu2 <- rexp(ns, 10)
  )
  brms_setup("posterior_predict:366",
    prep$dpars$mu3 <- rexp(ns, 10)
  )
  brms_setup("posterior_predict:367",
    pred <- brms_adapt_posterior_predict("dirichlet2", i = sample(1:nobs, 
        1), prep = prep)
  )
  brms_port("posterior_predict:368", "pass",
    "",
    expect_equal(dim(pred), c(ns, ncat))
  )
  brms_port("posterior_predict:369", "pass",
    "",
    expect_equal(rowSums(pred), rep(1, nrow(pred)))
  )
  brms_setup("posterior_predict:371",
    prep$family <- brmsfamily("logistic_normal")
  )
  brms_setup("posterior_predict:372",
    prep$dpars <- list(
      mu2 = rnorm(ns),
      mu3 = rnorm(ns),
      sigma2 = rexp(ns, 10),
      sigma3 = rexp(ns, 10)
    )
  )
  brms_setup("posterior_predict:378",
    prep$lncor <- rbeta(ns, 2, 1)
  )
  brms_setup("posterior_predict:379",
    pred <- brms_adapt_posterior_predict("logistic_normal", i = sample(1:nobs, 
        1), prep = prep)
  )
  brms_port("posterior_predict:380", "pass",
    "",
    expect_equal(dim(pred), c(ns, ncat))
  )
  brms_port("posterior_predict:381", "pass",
    "",
    expect_equal(rowSums(pred), rep(1, nrow(pred)))
  )
})

test_that("truncated posterior_predict run without errors", {
  withr::local_seed(384L)
  brms_setup("posterior_predict:385",
    ns <- 30
  )
  brms_setup("posterior_predict:386",
    nobs <- 15
  )
  brms_setup("posterior_predict:387",
    prep <- structure(list(ndraws = ns, nobs = nobs), class = "brmsprep")
  )
  brms_setup("posterior_predict:388",
    prep$dpars <- list(
      mu = matrix(rnorm(ns * nobs), ncol = nobs),
      sigma = rchisq(ns, 3)
    )
  )
  brms_setup("posterior_predict:392",
    prep$refcat <- 1
  )
  brms_setup("posterior_predict:394",
    prep$data <- list(lb = sample(-(4:7), nobs, TRUE))
  )
  brms_setup("posterior_predict:395",
    pred <- sapply(1:nobs, brms_adapt_posterior_predict, fun = "gaussian", 
        prep = prep)
  )
  brms_port("posterior_predict:396", "pass",
    "",
    expect_equal(dim(pred), c(ns, nobs))
  )
  brms_setup("posterior_predict:398",
    prep$dpars$mu <- exp(prep$dpars$mu)
  )
  brms_setup("posterior_predict:399",
    prep$data <- list(ub = sample(70:80, nobs, TRUE))
  )
  brms_setup("posterior_predict:400",
    pred <- sapply(1:nobs, brms_adapt_posterior_predict, fun = "poisson", 
        prep = prep)
  )
  brms_port("posterior_predict:401", "pass",
    "",
    expect_equal(dim(pred), c(ns, nobs))
  )
  brms_setup("posterior_predict:403",
    prep$data <- list(lb = rep(0, nobs), ub = sample(70:75, nobs, TRUE))
  )
  brms_setup("posterior_predict:404",
    pred <- sapply(1:nobs, brms_adapt_posterior_predict, fun = "poisson", 
        prep = prep)
  )
  brms_port("posterior_predict:405", "pass",
    "",
    expect_equal(dim(pred), c(ns, nobs))
  )
})

test_that("posterior_predict for the wiener diffusion model runs without errors", {
  withr::local_seed(408L)
  brms_setup("posterior_predict:409",
    brms_adapt_brms_skip("skip as long as RWiener fails on R-devel for 3.6.0")
  )
  brms_setup("posterior_predict:410",
    ns <- 5
  )
  brms_setup("posterior_predict:411",
    nobs <- 3
  )
  brms_setup("posterior_predict:412",
    prep <- structure(list(ndraws = ns, nobs = nobs), class = "brmsprep")
  )
  brms_setup("posterior_predict:413",
    prep$dpars <- list(
      mu = matrix(rnorm(ns * nobs), ncol = nobs),
      bs = rchisq(ns, 3), ndt = rep(0.5, ns),
      bias = rbeta(ns, 1, 1)
    )
  )
  brms_setup("posterior_predict:418",
    prep$data <- list(Y = abs(rnorm(ns)) + 0.5, dec = c(1, 0, 1))
  )
  brms_setup("posterior_predict:419",
    i <- sample(1:nobs, 1)
  )
  brms_port("posterior_predict:420", "pass",
    "",
    expect_equal(nrow(brms_adapt_posterior_predict("wiener", i, prep)), ns)
  )
})
